class Grandparent {
    public Grandparent() {
        System.out.println("[1] Grandparent constructor executed (extends Object)");
    }
}

class Parent extends Grandparent {
    public Parent() {
        // Implicit super() called here automatically!
        System.out.println("[2] Parent constructor executed");
    }
}

class Child extends Parent {
    public Child() {
        // Implicit super() called here automatically!
        System.out.println("[3] Child constructor executed");
    }
}

public class ExecutionTraceDemo {
    public static void main(String[] args) {
        System.out.println("--- Creating Child Instance ---");
        Child c = new Child();
        System.out.println("--- Instance fully initialized! ---");
    }
}

