activities.code:
class Vehicle {
    protected String registrationNumber;

    public Vehicle(String regNumber) {
        this.registrationNumber = regNumber;
        System.out.println("Vehicle registered with ID: " + registrationNumber);
    }
}

class Car extends Vehicle {
    protected int doors;

    public Car(String regNumber, int doors) {
        // Explicit super(regNumber) required because Vehicle has no default constructor!
        super(regNumber);
        this.doors = doors;
        System.out.println("Car initialized with " + doors + " doors");
    }
}

public class ParameterizedChainDemo {
    public static void main(String[] args) {
        Car myCar = new Car("KA-01-AB-1234", 4);
    }
}

