class NetworkResource {
    public NetworkResource(String ip) {
        System.out.println("[1] Network connection opened to: " + ip);
    }
}

class DatabaseConnection extends NetworkResource {
    public DatabaseConnection(String ip, String dbName) {
        super(ip);
        System.out.println("[2] Database " + dbName + " connected");
    }
}

class PooledConnection extends DatabaseConnection {
    public PooledConnection(String ip, String dbName, int poolId) {
        super(ip, dbName);
        System.out.println("[3] Pooled connection assigned slot #" + poolId);
    }
}

public class Main {
    public static void main(String[] args) {
        PooledConnection pool = new PooledConnection("192.168.1.50", "ProductionDB", 7);
    }
}
